// PDF -> G-code in browser
// Generated by Claude Opus 5

// Blot work area — must match DEFAULT_MAX_X/Y_MM in src/config.h
const MAX_X_MM = 125.0;
const MAX_Y_MM = 125.0;

const FEED_RATE = 4000;    // mm/min, drawing
const RAPID_RATE = 16000;  // mm/min, pen-up travel

const MIN_SEGMENT_MM = 0.3;    // skip paths shorter than this
const SIMPLIFY_TOL_MM = 0.05;  // Douglas-Peucker tolerance

// ───── marching squares (port of tools/contours.py) ─────

// Corner bits: 0=top-left 1=top-right 2=bottom-right 3=bottom-left.
// Each entry lists [entry_edge, exit_edge] pairs oriented so the low-valued
// region stays to the left, matching skimage.measure.find_contours.
const CASES = {
  0: [], 15: [],
  1: [["T", "L"]],
  2: [["R", "T"]],
  3: [["R", "L"]],
  4: [["B", "R"]],
  5: [["T", "L"], ["B", "R"]],   // saddle
  6: [["B", "T"]],
  7: [["B", "L"]],
  8: [["L", "B"]],
  9: [["T", "B"]],
  10: [["R", "T"], ["L", "B"]],  // saddle
  11: [["R", "B"]],
  12: [["L", "R"]],
  13: [["T", "R"]],
  14: [["L", "T"]],
};

// Moving off a cell through one edge enters the neighbour across it,
// arriving on that neighbour's opposite edge.
const STEP = {
  T: [-1, 0, "B"],
  B: [1, 0, "T"],
  L: [0, -1, "R"],
  R: [0, 1, "L"],
};

// Midpoint of a cell edge in (row, col). At level 0.5 on binary input every
// crossing is exactly halfway, so no interpolation is needed.
function edgePoint(r, c, edge) {
  switch (edge) {
    case "T": return [r, c + 0.5];
    case "B": return [r + 1.0, c + 0.5];
    case "L": return [r + 0.5, c];
    default:  return [r + 0.5, c + 1.0]; // R
  }
}

// binary: Uint8Array of 0/1, row-major, h rows x w cols.
function findContours(binary, w, h) {
  if (h < 2 || w < 2) return [];

  const at = (r, c) => binary[r * w + c];

  // segments keyed "r,c" -> array of [entry, exit]
  const segments = new Map();
  for (let r = 0; r < h - 1; r++) {
    for (let c = 0; c < w - 1; c++) {
      const code =
        (at(r, c) ? 1 : 0) |
        (at(r, c + 1) ? 2 : 0) |
        (at(r + 1, c + 1) ? 4 : 0) |
        (at(r + 1, c) ? 8 : 0);
      const pairs = CASES[code];
      if (pairs.length) segments.set(r + "," + c, pairs.map((p) => p.slice()));
    }
  }

  const contours = [];
  while (segments.size) {
    const startKey = segments.keys().next().value;
    const [sr, sc] = startKey.split(",").map(Number);
    const list = segments.get(startKey);
    const [entry, firstExit] = list.shift();
    if (!list.length) segments.delete(startKey);

    let cell = [sr, sc];
    let exit = firstExit;
    const points = [edgePoint(sr, sc, entry), edgePoint(sr, sc, exit)];
    let closed = false;

    for (;;) {
      const [dr, dc, arrive] = STEP[exit];
      const nr = cell[0] + dr, nc = cell[1] + dc;
      if (nr < 0 || nr >= h - 1 || nc < 0 || nc >= w - 1) break;
      if (nr === sr && nc === sc && arrive === entry) { closed = true; break; }

      const key = nr + "," + nc;
      const nxt = segments.get(key);
      if (!nxt) break;

      let idx = -1;
      for (let i = 0; i < nxt.length; i++) {
        if (nxt[i][0] === arrive) { idx = i; break; }
      }
      if (idx < 0) break;
      const [, nextExit] = nxt.splice(idx, 1)[0];
      if (!nxt.length) segments.delete(key);

      cell = [nr, nc];
      exit = nextExit;
      points.push(edgePoint(nr, nc, exit));
    }

    let full = points;
    if (closed) {
      const a = points[0], b = points[points.length - 1];
      if (a[0] !== b[0] || a[1] !== b[1]) points.push(a);
    } else {
      // Open contour: we started somewhere in the middle, so walk backwards
      // from the start too or the path comes out in fragments.
      full = extendBackwards(points, segments, [sr, sc], entry, w, h);
    }
    if (full.length >= 2) contours.push(full);
  }
  return contours;
}

// Walk backwards from an open contour's start to pick up the earlier half.
function extendBackwards(points, segments, startCell, startEntry, w, h) {
  const prefix = [];
  let cell = startCell;
  let entry = startEntry;

  for (;;) {
    const [dr, dc, arrive] = STEP[entry];
    const nr = cell[0] + dr, nc = cell[1] + dc;
    if (nr < 0 || nr >= h - 1 || nc < 0 || nc >= w - 1) break;

    const k = nr + "," + nc;
    const nxt = segments.get(k);
    if (!nxt) break;

    let idx = -1;
    for (let i = 0; i < nxt.length; i++) {
      if (nxt[i][1] === arrive) { idx = i; break; }
    }
    if (idx < 0) break;
    const [prevEntry] = nxt.splice(idx, 1)[0];
    if (!nxt.length) segments.delete(k);

    prefix.push(edgePoint(nr, nc, prevEntry));
    cell = [nr, nc];
    entry = prevEntry;
  }

  prefix.reverse();
  return prefix.concat(points);
}

// ───── path processing (port of pdf2gcode.py) ─────

function simplifyPath(pts, tol) {
  if (pts.length <= 2) return pts;

  const [sx, sy] = pts[0];
  const [ex, ey] = pts[pts.length - 1];
  const lx = ex - sx, ly = ey - sy;
  const len = Math.hypot(lx, ly);

  let maxDist = -1, maxIdx = 0;
  for (let i = 1; i < pts.length - 1; i++) {
    const vx = pts[i][0] - sx, vy = pts[i][1] - sy;
    let d;
    if (len < 1e-10) {
      d = Math.hypot(vx, vy);
    } else {
      const proj = (vx * lx + vy * ly) / (len * len);
      d = Math.hypot(vx - proj * lx, vy - proj * ly);
    }
    if (d > maxDist) { maxDist = d; maxIdx = i; }
  }

  if (maxDist <= tol) return [pts[0], pts[pts.length - 1]];
  const left = simplifyPath(pts.slice(0, maxIdx + 1), tol);
  const right = simplifyPath(pts.slice(maxIdx), tol);
  return left.slice(0, -1).concat(right);
}

// Nearest-neighbour ordering to cut pen-up travel.
function optimizeOrder(contours) {
  if (contours.length <= 1) return contours;

  const remaining = contours.map((_, i) => i);
  const ordered = [remaining.shift()];
  let end = contours[ordered[0]][contours[ordered[0]].length - 1];

  while (remaining.length) {
    let best = 0, bestDist = Infinity, bestRev = false;
    for (let i = 0; i < remaining.length; i++) {
      const c = contours[remaining[i]];
      const ds = Math.hypot(end[0] - c[0][0], end[1] - c[0][1]);
      const de = Math.hypot(end[0] - c[c.length - 1][0], end[1] - c[c.length - 1][1]);
      if (ds < bestDist) { bestDist = ds; best = i; bestRev = false; }
      if (de < bestDist) { bestDist = de; best = i; bestRev = true; }
    }
    const idx = remaining.splice(best, 1)[0];
    if (bestRev) contours[idx].reverse();
    ordered.push(idx);
    const c = contours[idx];
    end = c[c.length - 1];
  }
  return ordered.map((i) => contours[i]);
}

// ───── rasterise + threshold ─────

async function pdfToImageData(file, dpi) {
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
  const page = await pdf.getPage(1);

  // pdf.js viewport is in CSS px at 72dpi; scale up to the requested dpi.
  const viewport = page.getViewport({ scale: dpi / 72 });
  const canvas = document.createElement("canvas");
  canvas.width = Math.ceil(viewport.width);
  canvas.height = Math.ceil(viewport.height);
  const ctx = canvas.getContext("2d", { willReadFrequently: true });

  // White background: PDFs are transparent, and transparent would threshold
  // as black and flood the plot.
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  await page.render({ canvasContext: ctx, viewport }).promise;

  return ctx.getImageData(0, 0, canvas.width, canvas.height);
}

// Grayscale + crop whitespace, mirroring auto_crop() in pdf2gcode.py.
function toGrayCropped(img, doCrop, cropThreshold = 240, padding = 10) {
  const { width: w, height: h, data } = img;
  const gray = new Uint8Array(w * h);
  for (let i = 0, p = 0; i < data.length; i += 4, p++) {
    // Rec. 601 luma, same as PIL's "L" conversion.
    gray[p] = (data[i] * 299 + data[i + 1] * 587 + data[i + 2] * 114) / 1000;
  }
  if (!doCrop) return { gray, w, h };

  let rMin = h, rMax = -1, cMin = w, cMax = -1;
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (gray[r * w + c] < cropThreshold) {
        if (r < rMin) rMin = r;
        if (r > rMax) rMax = r;
        if (c < cMin) cMin = c;
        if (c > cMax) cMax = c;
      }
    }
  }
  if (rMax < 0) return { gray, w, h }; // nothing to crop

  rMin = Math.max(0, rMin - padding); rMax = Math.min(h - 1, rMax + padding);
  cMin = Math.max(0, cMin - padding); cMax = Math.min(w - 1, cMax + padding);

  const nw = cMax - cMin + 1, nh = rMax - rMin + 1;
  const out = new Uint8Array(nw * nh);
  for (let r = 0; r < nh; r++) {
    for (let c = 0; c < nw; c++) out[r * nw + c] = gray[(r + rMin) * w + (c + cMin)];
  }
  return { gray: out, w: nw, h: nh };
}

// ───── main entry ─────

export async function convertPdf(file, opts, onProgress) {
  const dpi = opts.dpi || 300;
  const threshold = opts.threshold ?? 128;
  const scaleFactor = opts.scale ?? 1.0;
  const margin = opts.margin ?? 2.0;
  const feed = opts.speed || FEED_RATE;

  onProgress?.("Rendering page 1…");
  const img = await pdfToImageData(file, dpi);

  onProgress?.("Tracing…");
  const { gray, w, h } = toGrayCropped(img, !opts.nocrop);

  const binary = new Uint8Array(w * h);
  for (let i = 0; i < gray.length; i++) binary[i] = gray[i] < threshold ? 1 : 0;

  // find_contours returns (row, col); swap to (x, y) like the Python does.
  let contours = findContours(binary, w, h).map((c) => c.map(([r, cc]) => [cc, r]));
  if (!contours.length) throw new Error("No contours found — try a higher threshold");

  onProgress?.(`Optimising ${contours.length} paths…`);
  contours = optimizeOrder(contours);

  onProgress?.("Generating G-code…");
  return contoursToGcode(contours, w, h, margin, scaleFactor, feed);
}

function contoursToGcode(contours, imgW, imgH, marginMm, scaleFactor, feed) {
  const usableX = (MAX_X_MM - 2 * marginMm) * scaleFactor;
  const usableY = (MAX_Y_MM - 2 * marginMm) * scaleFactor;
  const scale = Math.min(usableX / imgW, usableY / imgH);

  const drawW = imgW * scale, drawH = imgH * scale;
  const offX = marginMm + (usableX / scaleFactor - drawW) / 2;
  const offY = marginMm + (usableY / scaleFactor - drawH) / 2;

  // Flip Y: image Y=0 is top, plotter Y+ is up.
  const toMm = (px, py) => [px * scale + offX, (imgH - py) * scale + offY];
  const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);

  const out = [
    "; Generated in-browser by convert.js for Blot pen plotter",
    `; Drawing area: ${drawW.toFixed(1)}x${drawH.toFixed(1)}mm (scale ${scale.toFixed(4)} px->mm)`,
    "G21", "G90", "G92 X0 Y0", "M5",
  ];

  let paths = 0;
  for (const contour of contours) {
    if (contour.length < 2) continue;

    let pts = simplifyPath(contour.map(([x, y]) => toMm(x, y)), SIMPLIFY_TOL_MM);
    if (pts.length < 2) continue;

    let len = 0;
    for (let i = 1; i < pts.length; i++) {
      len += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    }
    if (len < MIN_SEGMENT_MM) continue;

    pts = pts.map(([x, y]) => [
      clamp(x, marginMm, MAX_X_MM - marginMm),
      clamp(y, marginMm, MAX_Y_MM - marginMm),
    ]);

    out.push(`G1 X${pts[0][0].toFixed(3)} Y${pts[0][1].toFixed(3)} F${RAPID_RATE}`);
    out.push("M3");
    for (let i = 1; i < pts.length; i++) {
      out.push(`G1 X${pts[i][0].toFixed(3)} Y${pts[i][1].toFixed(3)} F${feed}`);
    }
    out.push("M5");
    paths++;
  }

  out.push(`G1 X0 Y0 F${RAPID_RATE}`);
  out.push("M18");
  return { gcode: out.join("\n") + "\n", paths };
}
